INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K028', '肺循環と体循環', 'physiology', ARRAY['心臓','肺循環','体循環']::text[], ARRAY['肺循環と体循環とは？']::text[], '肺循環は心臓と肺を結ぶ流れ、体循環は心臓と全身を結ぶ流れです。', '教材は心臓を酸素の運搬を支えるポンプとして説明しています。', ARRAY['P040','P160','P164']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I037']::text[], ARRAY[4]::integer[], ARRAY['I037']::text[], '[{"issue_id":"I037","rule":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K029', 'SpO₂の読み方', 'observation', ARRAY['SpO₂','酸素飽和度','パルスオキシメータ']::text[], ARRAY['SpO₂の読み方とは？']::text[], 'SpO₂は、血液中のヘモグロビンと酸素の結び付きの割合を推定する指標です。', '測定には誤差や限界があります。値だけで健康・不調を判定せず、症状や測定条件も含めて扱います。', ARRAY['P041','P158']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], ARRAY['EXT05']::text[], '{}', 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I019','I035']::text[], ARRAY[4]::integer[], ARRAY['I019','I035']::text[], '[{"issue_id":"I019","rule":"SpO₂の数値だけで健康状態を採点しません。測定条件や症状も含めて扱います。"},{"issue_id":"I035","rule":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K030', 'ミトコンドリアの構造', 'cell_energy', ARRAY['ミトコンドリア','内膜','クリステ','マトリックス']::text[], ARRAY['ミトコンドリアの構造とは？']::text[], '教材では外膜・内膜・クリステ・マトリックスを紹介しています。クリステは内膜のひだです。', 'ATPの説明は共通知識に統合しています。', ARRAY['P042']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[5]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K031', '活性酸素の教材内での位置付け', 'cell_energy', ARRAY['活性酸素','酸化ストレス']::text[], ARRAY['活性酸素の教材内での位置付けとは？']::text[], '教材は、活性酸素を単に悪いものとせず、情報伝達や防御にも関係するものとして説明しています。', '過剰な状態の説明と通常の働きを分けます。呼吸法や食品で老化を防ぐという保証には使いません。', ARRAY['P045']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[5]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K032', '交感神経と副交感神経', 'mind', ARRAY['自律神経','交感神経','副交感神経']::text[], ARRAY['交感神経と副交感神経とは？']::text[], '交感神経と副交感神経は、どちらも命を支える働きを持ちます。', '教材は必要なときに状態を切り替えることを大切にしています。交感神経は悪い、副交感神経は常によい、とは扱いません。', ARRAY['P046','P173','P180','P181']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C034']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I041']::text[], ARRAY[6]::integer[], ARRAY['I041']::text[], '[{"issue_id":"I041","rule":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K033', 'HRVとは', 'observation', ARRAY['HRV','心拍変動','R-R間隔']::text[], ARRAY['HRVとはとは？']::text[], '心拍変動（HRV）は心臓の拍動の間隔が少しずつ変化することです。', '教材でも、高ければ必ず健康、低ければ必ず不調とは判断しないとしています。呼吸・姿勢・活動・睡眠などの状況と一緒に扱います。', ARRAY['P047','P178','P185']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C034']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I041','I042']::text[], ARRAY[6]::integer[], ARRAY['I041','I042']::text[], '[{"issue_id":"I041","rule":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。"},{"issue_id":"I042","rule":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K034', '長い呼気の考え方', 'mind', ARRAY['長い呼気','休息']::text[], ARRAY['長い呼気の考え方とは？']::text[], '教材では吸う息より吐く息を長くする練習を紹介しています。', '苦しくなるまで長く吐く練習にはしません。秒数・回数は呼吸法カードに章ごとに保存しています。', ARRAY['P048','P175','P184']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C008','C034']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I022','I041','I043']::text[], ARRAY[6]::integer[], ARRAY['I022','I041','I043']::text[], '[{"issue_id":"I022","rule":"基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。"},{"issue_id":"I041","rule":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。"},{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K035', '自動の呼吸と意識的な呼吸', 'mind', ARRAY['延髄','橋','呼吸中枢']::text[], ARRAY['自動の呼吸と意識的な呼吸とは？']::text[], '教材は、延髄や橋などによる自動調整と、意識して呼吸を変える働きを説明しています。', '呼吸は自動調整と意識的調整が交わる働きとして学びます。', ARRAY['P049','P193']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C011']::text[], 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[7]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K036', '呼吸を変えることが不安なとき', 'mind', ARRAY['不安','観察','パニック']::text[], ARRAY['呼吸を変えることが不安なときとは？']::text[], '教材では、呼吸の操作が怖く感じられる場合は、まず呼吸を観察することから始めるとしています。', '不安や息苦しさの原因をこの項目だけで決めません。強く深く吸うことを一律に求めません。', ARRAY['P050','P189']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C001','C011']::text[], 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[7]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K037', '呼吸と集中の準備', 'mind', ARRAY['ゾーン','フロー','集中']::text[], ARRAY['呼吸と集中の準備とは？']::text[], '教材は呼吸を集中へ戻るきっかけとして紹介しています。', '呼吸をすれば必ずゾーンに入れるわけではない、と明記されています。練習・準備・経験と組み合わせて学ぶ位置付けです。', ARRAY['P051','P191','P197']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C011']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I045']::text[], ARRAY[7]::integer[], ARRAY['I045']::text[], '[{"issue_id":"I045","rule":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K038', '眠ろうと頑張りすぎない', 'sleep', ARRAY['睡眠','就寝前']::text[], ARRAY['眠ろうと頑張りすぎないとは？']::text[], '教材では、眠るために呼吸を頑張りすぎず、楽な姿勢とやさしい呼吸を大切にします。', '就寝前の呼吸法を不眠の診断や治療の代わりとして説明しません。', ARRAY['P052','P198']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C015','C016','C017']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I026']::text[], ARRAY[8]::integer[], ARRAY['I026']::text[], '[{"issue_id":"I026","rule":"名称案：就寝前のやさしい呼吸（第8章・保息なし）。原図の4秒吸う・7〜8秒吐くを記録し、7秒の保息は追加しない。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K039', '睡眠時無呼吸とは', 'sleep', ARRAY['睡眠時無呼吸','OSA','CSA']::text[], ARRAY['睡眠時無呼吸とはとは？']::text[], '睡眠中に呼吸が何度も止まったり再開したりする状態を睡眠時無呼吸として扱います。', '教材は上気道の閉塞に関係する型と、脳の呼吸調節に関係する型を区別しています。呼吸法だけで治るとは説明しません。', ARRAY['P053','P210','P211']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], ARRAY['EXT06']::text[], ARRAY['C015','C016','C017']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I040']::text[], ARRAY[8]::integer[], ARRAY['I040']::text[], '[{"issue_id":"I040","rule":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K040', '睡眠の相談を専門家につなぐ目安', 'safety', ARRAY['いびき','眠気','専門家','相談']::text[], ARRAY['睡眠の相談を専門家につなぐ目安とは？']::text[], '教材では、呼吸が止まると言われる、強いいびきが続く、日中の強い眠気があるなどの場合に医療機関への相談を勧める方針です。', '呼吸マネージャーやAI先生が睡眠時無呼吸・不眠を診断するためのチェック表にはしません。', ARRAY['P054','P199','P205','P210']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], ARRAY['EXT07']::text[], '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[8]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K041', '回復のための呼吸の位置付け', 'conditioning', ARRAY['疲労','回復']::text[], ARRAY['回復のための呼吸の位置付けとは？']::text[], '教材では、休息へ向かうきっかけとして3分リカバリー呼吸を紹介しています。', '多く吸うことや苦しいほど長く吐くことを目的にしません。疲労の原因を呼吸だけで決める項目ではありません。', ARRAY['P056','P213','P215','P175']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C010','C018','C019','C020','C021']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I048']::text[], ARRAY[6,9]::integer[], ARRAY['I048']::text[], '[{"issue_id":"I048","rule":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K042', '冷えと呼吸の扱い', 'conditioning', ARRAY['冷え','体温','生活習慣']::text[], ARRAY['冷えと呼吸の扱いとは？']::text[], '教材は、冷えに対して呼吸と生活習慣を一緒に振り返る考え方を紹介しています。', '呼吸だけで体温が大きく上がる、冷えがすべて改善する、とは説明しません。', ARRAY['P057']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C018','C019','C020','C021']::text[], 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[9]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K043', '運動直後の呼吸', 'conditioning', ARRAY['運動後','クールダウン']::text[], ARRAY['運動直後の呼吸とは？']::text[], '教材では、運動直後に呼吸が大きく乱れている間は秒数を無理に合わせず、自然な呼吸から徐々に整えるとしています。', '息苦しさ・めまい・胸の痛みがある場合は無理に続けず休むという注意を、実践カードにも保持しています。', ARRAY['P058']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C018','C019','C020','C021']::text[], 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[9]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K044', '腹式呼吸とお腹の動き', 'gut', ARRAY['腹式呼吸','横隔膜','腹部']::text[], ARRAY['腹式呼吸とお腹の動きとは？']::text[], '教材では腹式呼吸を、お腹だけを大きく動かす呼吸とは説明していません。', '横隔膜に伴う自然なお腹の動きに気づく練習として紹介しています。無理にお腹を膨らませたり胸を押さえたりしません。', ARRAY['P059','P216']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C022','C023','C024','C025','C026']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I048']::text[], ARRAY[10]::integer[], ARRAY['I048']::text[], '[{"issue_id":"I048","rule":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K045', '腹圧とは', 'gut', ARRAY['腹圧','体幹','骨盤底']::text[], ARRAY['腹圧とはとは？']::text[], '腹圧はお腹の中の圧力です。教材では姿勢・体幹の支えと関わるものとして扱います。', '腹圧は高ければよいとは説明せず、必要なときに支え、不要なときにはゆるめることを学びます。', ARRAY['P060']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C022','C023','C024','C025','C026']::text[], 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[10]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K046', '腸脳相関とは', 'gut', ARRAY['腸脳相関','腸','脳']::text[], ARRAY['腸脳相関とはとは？']::text[], '腸と脳が神経・ホルモン・免疫などを通じて互いに影響し合う関係を、教材では腸脳相関と呼んでいます。', '呼吸だけですべての腸の不調が解決するとは説明しません。', ARRAY['P061','P216']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C022','C023','C024','C025','C026']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I048']::text[], ARRAY[10]::integer[], ARRAY['I048']::text[], '[{"issue_id":"I048","rule":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K047', '食前と食後の使い分け', 'gut', ARRAY['食前','食後','休息']::text[], ARRAY['食前と食後の使い分けとは？']::text[], '教材では食前は落ち着いて食事に入る準備、食後は体を休める場面として区別しています。', '便秘や胃腸の不調の改善を保証する目的タグにはしません。', ARRAY['P062']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C022','C023','C024','C025','C026']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I027']::text[], ARRAY[10]::integer[], ARRAY['I027']::text[], '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K048', '生活に呼吸を取り入れる', 'lifestyle', ARRAY['生活習慣','朝','昼','夜']::text[], ARRAY['生活に呼吸を取り入れるとは？']::text[], '教材は朝・昼・夜など、生活の中で呼吸に気づく時間を決める方法を紹介しています。', '最初からすべてを行うのではなく、取り入れやすい場面から始めるという学習方針です。', ARRAY['P063','P217','P218','P200']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C018','C019','C020','C021','C022','C023','C024','C025','C026']::text[], 'editorial_draft', 'traditional_explanation', true, false, false, '{}', ARRAY[8,11]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K049', 'アーユルヴェーダの教材内での扱い', 'lifestyle', ARRAY['アーユルヴェーダ','伝統','生活']::text[], ARRAY['アーユルヴェーダの教材内での扱いとは？']::text[], 'この教材ではアーユルヴェーダを、インドで発展した伝統的な健康観として紹介しています。', '食事・睡眠・季節・生活リズムを一緒に見る考え方として学び、医学的な診断や治療には用いません。', ARRAY['P064','P217']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C018','C019','C020','C021']::text[], 'editorial_draft', 'traditional_explanation', true, false, false, '{}', ARRAY[11]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K050', 'ドーシャをどう扱うか', 'lifestyle', ARRAY['ドーシャ','ヴァータ','ピッタ','カパ']::text[], ARRAY['ドーシャをどう扱うかとは？']::text[], '教材はヴァータ・ピッタ・カパを、自分の傾向や今日の状態を振り返る伝統的な枠組みとして紹介しています。', '医学的な診断名や固定的な人物分類にはしません。分類だけを理由に呼吸法を自動処方しない設計です。', ARRAY['P065']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'traditional_explanation', true, false, false, '{}', ARRAY[11]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K051', '本番で呼吸を使う4つの目的', 'performance', ARRAY['本番前','切り替え','動作','力発揮']::text[], ARRAY['本番で呼吸を使う4つの目的とは？']::text[], '教材は本番前の準備、ミス後の切り替え、動作とのリズム、力を出す場面を分けています。', '場面ごとの技法を混ぜず、競技成績や成功を保証する説明には使いません。', ARRAY['P066','P220']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C027','C028','C029','C030']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I029']::text[], ARRAY[12]::integer[], ARRAY['I029']::text[], '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K052', '競技による呼吸の違い', 'performance', ARRAY['スポーツ','競技','持久','パワー']::text[], ARRAY['競技による呼吸の違いとは？']::text[], '教材では持久系・パワー系・間欠ダッシュ系・精密集中系・水中系の課題を分けています。', '水中の実践や強い負荷の運動へ、日常向けの呼吸手順を自動転用しません。', ARRAY['P067','P221']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C027','C028','C029','C030']::text[], 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[12]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K053', '試合の前・中・後の使い分け', 'performance', ARRAY['試合前','試合中','試合後']::text[], ARRAY['試合の前・中・後の使い分けとは？']::text[], '教材では試合前は準備、試合中は動作や判断への復帰、試合後は徐々に落ち着くことを目的にしています。', '各場面を個別カードの参照先として保持します。', ARRAY['P068']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C027','C028','C029','C030']::text[], 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[12]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K054', '声と呼気', 'voice', ARRAY['声','声帯','呼気']::text[], ARRAY['声と呼気とは？']::text[], '教材では呼気が声帯を通るときの振動を、声が生まれる基本として説明しています。', '声には呼吸・声帯・共鳴・発音などが関係します。「声の質のすべてが呼吸で決まる」とは説明しません。胸や頭に感じる響きと解剖学的な共鳴腔の区別は監修対象です。', ARRAY['P069','P223']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C031','C032','C033']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I049']::text[], ARRAY[13]::integer[], ARRAY['I049']::text[], '[{"issue_id":"I049","rule":"声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K055', 'お腹から声を出すという表現', 'voice', ARRAY['腹圧','声','横隔膜']::text[], ARRAY['お腹から声を出すという表現とは？']::text[], 'お腹から直接声が出るという意味ではありません。教材では呼吸や体の支えによって声を支えるという意味で使っています。', 'お腹を強く固めたり、喉で押し出したりする指示にはしません。', ARRAY['P070']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C031','C032','C033']::text[], 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[13]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K056', '声の練習を中止する目安', 'safety', ARRAY['声枯れ','喉','痛み']::text[], ARRAY['声の練習を中止する目安とは？']::text[], '教材では声がかすれる、痛みがある、長く不調が続く場合は、無理に練習を続けないとしています。', '症状が続く場合の専門家への相談方針を保持しています。病気の診断や練習の続行判断はしません。', ARRAY['P071']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I028']::text[], ARRAY[13]::integer[], ARRAY['I028']::text[], '[{"issue_id":"I028","rule":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K057', '落ち着く・集中する・切り替える', 'performance', ARRAY['メンタル','本番','目的']::text[], ARRAY['落ち着く・集中する・切り替えるとは？']::text[], '教材は本番で呼吸を使う目的を、落ち着く、集中する、切り替えるなどに分けています。', '呼吸ですべての練習が不要になるとは説明しません。同名技法の秒数差は別の手順として保持します。', ARRAY['P072','P225','P226','P228']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C027','C028']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I029']::text[], ARRAY[14]::integer[], ARRAY['I029']::text[], '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K058', '本番前のルーティンを考える', 'performance', ARRAY['試験','プレゼン','ルーティン']::text[], ARRAY['本番前のルーティンを考えるとは？']::text[], '教材は学生と社会人それぞれの場面に合わせ、姿勢・呼吸・自分にかける言葉を準備する方法を紹介しています。', '学生向け3分、社会人向け1分という例は教材の例として保存し、年齢だけで自動適用しません。', ARRAY['P073','P188','P227','P222']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C027','C028']::text[], 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I044']::text[], ARRAY[7,12,14]::integer[], ARRAY['I044']::text[], '[{"issue_id":"I044","rule":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K059', 'ヨガをどう学ぶか', 'yoga_theory', ARRAY['ヨガ','アーサナ','瞑想']::text[], ARRAY['ヨガをどう学ぶかとは？']::text[], 'この教材ではヨガを、身体・呼吸・心・生活・集中・瞑想を含む体系として学びます。', 'ポーズの形だけでなく、自分の状態への気づきを重視しています。', ARRAY['P074','P229','P230']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'traditional_explanation', true, false, false, '{}', ARRAY[15]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K060', 'ヨガの歴史と文献', 'yoga_theory', ARRAY['ヨガ史','ヴェーダ','ヨーガ・スートラ','パタンジャリ']::text[], ARRAY['ヨガの歴史と文献とは？']::text[], '教材はヴェーダ、ウパニシャッド、バガヴァッド・ギーター、ヨーガ・スートラなどを紹介しています。', '年代を断定する項目ではなく、教材内で各文献がどのように位置付けられるかを学ぶための整理です。', ARRAY['P075']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'traditional_explanation', true, false, false, '{}', ARRAY[15]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K061', 'ヨガの実践体系の分類', 'yoga_theory', ARRAY['カルマ','ジュニャーナ','バクティ','クリヤー','ハタ','ラージャ']::text[], ARRAY['ヨガの実践体系の分類とは？']::text[], '教材の大分類はカルマ・ジュニャーナ・バクティ・クリヤーの4つです。', '補足のハタ・ラージャなどとは分類の位置付けを分けます。全流派に共通する唯一の分類とは扱いません。', ARRAY['P076','P231']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'traditional_explanation', true, false, false, ARRAY['I051']::text[], ARRAY[15,16]::integer[], ARRAY['I051']::text[], '[{"issue_id":"I051","rule":"八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K062', '八支則の8つの要素', 'yoga_theory', ARRAY['八支則','八支','8段階']::text[], ARRAY['八支則の8つの要素とは？']::text[], '教材はヤマ、ニヤマ、アーサナ、プラーナーヤーマ、プラティヤハーラ、ダーラナー、ディヤーナ、サマーディを紹介しています。', '生活の土台、身体、呼吸、感覚、集中、瞑想、統合をつなぐ学習上の整理です。', ARRAY['P077','P231']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'traditional_explanation', true, false, false, ARRAY['I051']::text[], ARRAY[16]::integer[], ARRAY['I051']::text[], '[{"issue_id":"I051","rule":"八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K063', 'ヤマとニヤマ', 'yoga_theory', ARRAY['ヤマ','ニヤマ','アヒンサー','自己観察']::text[], ARRAY['ヤマとニヤマとは？']::text[], '教材ではヤマを人との関わり方、ニヤマを自分自身の整え方として紹介しています。', '呼吸の秒数や技法ではなく、無理をしない・観察する・継続するなどの生活態度につなげています。', ARRAY['P078']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'traditional_explanation', true, false, false, '{}', ARRAY[16]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K064', '呼吸から姿勢を見直す', 'yoga_theory', ARRAY['アーサナ','姿勢','呼吸']::text[], ARRAY['呼吸から姿勢を見直すとは？']::text[], '教材は、ポーズの形よりも呼吸が続くことを大切にしています。', '呼吸が苦しい場合は姿勢をゆるめるという学習方針です。難しい姿勢へ誘導する項目ではありません。', ARRAY['P079']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', '{}', 'editorial_draft', 'traditional_explanation', true, false, false, '{}', ARRAY[16]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K065', '呼吸観察から集中へ', 'yoga_theory', ARRAY['集中','瞑想','呼吸観察']::text[], ARRAY['呼吸観察から集中へとは？']::text[], '教材は楽な姿勢で自然な呼吸に気づき、注意がそれたら責めずに戻る練習を紹介しています。', 'まず気づきから始め、すべての呼吸を強くコントロールしないという考え方です。', ARRAY['P080']::text[], ARRAY['原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。']::text[], '{}', ARRAY['C001']::text[], 'editorial_draft', 'traditional_explanation', true, false, false, '{}', ARRAY[16]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K066', '二酸化炭素が体外へ出るまで', 'physiology', ARRAY['CO₂','二酸化炭素','静脈','呼気']::text[], ARRAY['二酸化炭素が体外へ出るまでとは？']::text[], '細胞で生じた二酸化炭素は血液で心臓・肺へ運ばれ、肺胞から呼気として体外へ出ます。', '酸素を届ける流れと、二酸化炭素を戻す流れを対にして学びます。血中の運搬形態や割合はこの図から補いません。', ARRAY['P166']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], ARRAY['EXT01']::text[], '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[4]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K067', '赤血球とヘモグロビンを区別する', 'physiology', ARRAY['赤血球','ヘモグロビン','Hb']::text[], ARRAY['赤血球とヘモグロビンを区別するとは？']::text[], 'ヘモグロビンは赤血球の中にある、酸素を運ぶたんぱく質です。', '教材のタクシーはヘモグロビンを説明する比喩です。「満員になってから出発」「全て空席になる」を実際の循環の条件として説明しません。', ARRAY['P162','P163']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], ARRAY['EXT01']::text[], '{}', 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I036']::text[], ARRAY[4]::integer[], ARRAY['I036']::text[], '[{"issue_id":"I036","rule":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K068', '細胞の構造を工場にたとえる', 'cell_energy', ARRAY['細胞膜','核','リボソーム','小胞体','ゴルジ体']::text[], ARRAY['細胞の構造を工場にたとえるとは？']::text[], '教材は細胞膜を工場の壁、核を設計情報、ミトコンドリアをエネルギー利用に関わる場所として紹介しています。', 'リボソーム、小胞体、ゴルジ体も役割別に示されています。代表的な細胞の模式図であり、すべての細胞が同じ構成という意味ではありません。', ARRAY['P167']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[5]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K069', '細胞呼吸と火のたとえ', 'cell_energy', ARRAY['細胞呼吸','燃焼','比喩']::text[], ARRAY['細胞呼吸と火のたとえとは？']::text[], '教材の「燃焼ではない」は、体内に炎が燃えているわけではないという説明として読みます。', '栄養と酸素を利用する細胞内の過程を学ぶ比喩です。火との比較図を、そのまま厳密な化学反応式や熱が出ないという説明にしません。', ARRAY['P169']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[5]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K070', '疲労や眠気と教材の説明の範囲', 'safety', ARRAY['疲労','眠気','酸素不足','ATP不足']::text[], ARRAY['疲労や眠気と教材の説明の範囲とは？']::text[], '教材には疲労や眠気と酸素・ATP・睡眠の関係が示されていますが、症状だけで原因を決める項目ではありません。', 'AI先生は「疲れるのはATP不足」「眠いのは低酸素」と断定せず、教材の一般説明と本人の状態の判断を分けます。', ARRAY['P159','P172','P211']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I040']::text[], ARRAY[4,5,8]::integer[], ARRAY['I040']::text[], '[{"issue_id":"I040","rule":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K071', '圧受容体反射の学習', 'physiology', ARRAY['圧受容体','圧受容体反射','血圧']::text[], ARRAY['圧受容体反射の学習とは？']::text[], '教材は血圧の変化に対する調整を、頸動脈洞・大動脈弓・延髄を含む図で紹介しています。', '呼吸との関連を学ぶ項目です。図の呼吸回数や血圧の波形を本人の治療目標にしません。原稿は高血圧等を呼吸法だけで改善すると説明しない方針です。', ARRAY['P174']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I043']::text[], ARRAY[6]::integer[], ARRAY['I043']::text[], '[{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K072', '呼吸を案内するときの言葉', 'safety', ARRAY['声かけ','指導','安全','HRV']::text[], ARRAY['呼吸を案内するときの言葉とは？']::text[], '教材では「苦しくない範囲」「頑張りすぎない」「吐く時間を少し長く」といった声かけを紹介しています。', '「病気が治る」「我慢して続ける」「HRVが高いほど健康」という説明を避ける方針です。めまいなどの中止条件も一緒に伝えます。', ARRAY['P177']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[6]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K073', '恒常性（ホメオスタシス）', 'physiology', ARRAY['恒常性','ホメオスタシス']::text[], ARRAY['恒常性（ホメオスタシス）とは？']::text[], '教材は恒常性を、体内の環境を一定に保とうとする働きとして説明しています。', '体温・血圧・pHなどが学習例です。呼吸法だけであらゆる値が正常になるという意味ではありません。', ARRAY['P178']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[6]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K074', '闘争・逃走反応と本番の緊張', 'mind', ARRAY['闘争逃走反応','緊張','ストレス','手汗']::text[], ARRAY['闘争・逃走反応と本番の緊張とは？']::text[], '教材では、危険やプレッシャーに対応する身体反応として心拍・呼吸・筋緊張などの変化を紹介しています。', '本番の緊張を必ずゼロにするという目標ではなく、本人が動きやすい状態を考えるための説明です。反応だけで診断しません。', ARRAY['P182','P226']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[6,14]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K075', '呼吸性の心拍変動', 'observation', ARRAY['呼吸性心拍変動','RSA','R-R間隔']::text[], ARRAY['呼吸性の心拍変動とは？']::text[], '教材は呼吸に伴う心拍数や拍動間隔の変化を紹介しています。', '心拍数とR-R間隔は同じ量ではありません。原図の軸・単位・波形方向は監修待ちのため、その図を健康度の採点や効果の判定には使いません。', ARRAY['P185']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, ARRAY['I041','I042']::text[], ARRAY[6]::integer[], ARRAY['I041','I042']::text[], '[{"issue_id":"I041","rule":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。"},{"issue_id":"I042","rule":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。"}]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K076', '扁桃体の教材上の説明', 'mind', ARRAY['扁桃体','不安','恐怖']::text[], ARRAY['扁桃体の教材上の説明とは？']::text[], '教材は扁桃体を恐怖や不安に関わる領域として紹介し、警報装置にたとえています。', 'この比喩だけですべての感情や症状を説明するものではありません。特定の呼吸で必ず扁桃体が鎮まるという保証には使いません。', ARRAY['P194']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[7]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K077', '前頭前野と準備した力', 'mind', ARRAY['前頭前野','判断','集中','計画']::text[], ARRAY['前頭前野と準備した力とは？']::text[], '教材は前頭前野を思考・判断・計画・集中・感情調整に関わる領域として紹介しています。', '原稿は呼吸だけで能力が急に上がるわけではないと述べ、知識・経験・技術・練習と組み合わせる位置付けにしています。', ARRAY['P195']::text[], ARRAY['原図の目視確認に基づく編集要約。原文引用ではない。']::text[], '{}', '{}', 'editorial_draft', 'educational_explanation', true, false, false, '{}', ARRAY[7]::integer[], '{}', '[]'::jsonb, '5.0') ON CONFLICT (knowledge_id) DO NOTHING;